cases.old:
taskConfig := atc.TaskConfig{}
if configSource.Config != nil {
	taskConfig = *configSource.Config
}
return taskConfig, nil

cases.new:
if configSource.Config == nil {
	return atc.TaskConfig{}, fmt.Errorf("task config is required")
}
return *configSource.Config, nil

if taskConfig.Limits == nil {
	return atc.TaskConfig{}, fmt.Errorf("task config limits are required")
}

if configSource.Limits.CPU != nil && taskConfig.Limits.CPU == nil {
	taskConfig.Limits.CPU = configSource.Limits.CPU
}
